//! Native Nix text for exported and reconciled configuration, without a second format.
//!
//! Nothing here reads credentials: the typed configuration only holds secret references.

use core::{error::Error as StdError, fmt};

use serde_json::Value;

use crate::Config;

/// Identifies regular native files explicitly initialized/owned by the application.
pub const MUTABLE_HEADER: &str = "# Mailstronaut editable configuration\n";
/// Identifies native files generated by the optional module (also emitted by Nix).
pub const MANAGED_HEADER: &str = "# Managed by programs.mailstronaut\n";

/// A redacted serialization failure.
#[derive(Debug)]
pub struct Error;
impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("unable to serialize native configuration")
    }
}
impl StdError for Error {}

/// Render data with the existing Snix serializer, without another Nix implementation.
/// # Errors
/// Rejects unsupported values or output exceeding the native source budget.
pub fn to_nix(value: &Value) -> Result<String, Error> {
    let mut text = snix_serde::to_string(value).map_err(|_| Error)?;
    text.push('\n');
    if text.len() > crate::MAX_SOURCE_BYTES {
        return Err(Error);
    }
    Ok(text)
}

/// Preserve declared keys without the pinned `deserialize_any` string-display bug.
/// Only the resource-limited evaluator child uses this with user source.
pub(crate) fn raw_data(source: &str) -> Result<Value, Error> {
    if source.len() > crate::MAX_SOURCE_BYTES {
        return Err(Error);
    }
    // The pinned bridge's generic string visitor returns Nix display quotes. Its
    // typed String path is correct. Use the evaluator's standard JSON builtin
    // internally, rather than a second evaluator/deserializer or a dependency fork.
    let json: String =
        snix_serde::from_str(&format!("builtins.toJSON (\n{source}\n)")).map_err(|_| Error)?;
    if json.len() > crate::helper::MAX_RESPONSE_BYTES {
        return Err(Error);
    }
    serde_json::from_str(&json).map_err(|_| Error)
}

/// Merge declared data into the current configuration.
///
/// Declared attributes win; attribute sets merge recursively, and everything else
/// (scalars, nulls and whole lists) replaces the current value. Attributes the user's
/// declaration leaves out keep their current value.
pub fn merge(current: &mut Value, declared: Value) {
    match (current, declared) {
        (Value::Object(current), Value::Object(declared)) => {
            for (key, value) in declared {
                match current.get_mut(&key) {
                    Some(slot) => merge(slot, value),
                    None => {
                        current.insert(key, value);
                    }
                }
            }
        }
        (slot, declared) => *slot = declared,
    }
}

/// A native attribute set the user can adopt in Home Manager or install directly. It
/// omits unset values and the ownership flag, which belongs to the deployment.
///
/// # Errors
/// Rejects invalid configuration, serialization failures or excess native source.
pub fn export(config: &Config) -> Result<String, Error> {
    if !config.validate().is_empty() {
        return Err(Error);
    }
    let mut value = serde_json::to_value(config).map_err(|_| Error)?;
    if let Value::Object(fields) = &mut value {
        fields.remove("managed");
    }
    strip_nulls(&mut value);
    to_nix(&value)
}

fn strip_nulls(value: &mut Value) {
    match value {
        Value::Object(fields) => {
            fields.retain(|_, item| !item.is_null());
            for item in fields.values_mut() {
                strip_nulls(item);
            }
        }
        Value::Array(items) => {
            for item in items {
                strip_nulls(item);
            }
        }
        _ => {}
    }
}

/// Set ownership on an attribute set; return false without changing other values.
#[must_use]
pub fn set_managed(value: &mut Value, managed: bool) -> bool {
    if let Value::Object(fields) = value {
        fields.insert("managed".into(), Value::Bool(managed));
        true
    } else {
        false
    }
}

#[cfg(test)]
#[expect(
    clippy::unwrap_used,
    reason = "Synthetic tests assert directly on encoded fixtures."
)]
mod tests {
    use serde_json::{Value, json};

    use super::{export, merge, set_managed, to_nix};
    use crate::Config;

    fn evaluate(text: &str) -> Value {
        super::raw_data(text).expect("raw evaluated data")
    }

    #[test]
    fn hostile_strings_and_keys_survive_a_round_trip_as_inert_data() {
        let value = json!({
            "plain": "ordinary",
            "with space": "not an identifier",
            "in": "reserved word",
            "quote": "a \"quoted\" \\ back\\slash",
            "interpolation": "${builtins.readFile /etc/passwd} and $HOME and $${x}",
            "lines": "first\nsecond\r\n\ttabbed",
            "unicode": "Réinscription · 世界",
            "list": [1, true, null, "x", [], {}],
            "nested": {"empty": {}, "number": 42},
        });
        assert_eq!(
            evaluate(&to_nix(&value).expect("native serialization")),
            value
        );
    }

    #[test]
    fn declared_values_win_while_undeclared_ones_and_whole_lists_follow_the_contract() {
        let mut current = json!({
            "appearance": "dark",
            "sync": {"pollSeconds": 60, "initialDays": 7},
            "accounts": [{"id": "ui-added"}],
            "notifications": {"showPreview": true},
        });
        merge(
            &mut current,
            json!({
                "appearance": "light",
                "sync": {"pollSeconds": 300},
                "accounts": [{"id": "declared"}],
            }),
        );
        assert_eq!(
            current,
            json!({
                "appearance": "light",
                "sync": {"pollSeconds": 300, "initialDays": 7},
                "accounts": [{"id": "declared"}],
                "notifications": {"showPreview": true},
            })
        );
        // An explicit empty list disables accounts; a missing one would have kept them.
        merge(&mut current, json!({"accounts": []}));
        assert_eq!(current["accounts"], json!([]));
    }

    #[test]
    fn export_round_trips_the_typed_configuration_and_drops_ownership_and_unset_values() {
        let source = r#"{
          schemaVersion = 1;
          managed = true;
          appearance = "dark";
          sync.pollSeconds = 120;
          accounts = [{
            id = "work";
            provider = "manual";
            address = "person@example.test";
            displayName = "Work ${"$"}{not interpolated}";
            userName = "person";
            imap = { host = "imap.example.test"; port = 993; security = "tls"; };
            smtp = { host = "smtp.example.test"; port = 587; security = "starttls"; };
            auth = { kind = "password"; secretRef = "work-password"; };
          }];
        }"#;
        let config: Config = snix_serde::from_str(source).unwrap();
        assert_eq!(config.validate(), []);
        let exported = export(&config).unwrap();
        assert!(!exported.contains("managed"));
        assert!(!exported.contains("null"));
        let reparsed: Config = snix_serde::from_str(&exported).unwrap();
        assert_eq!(reparsed.validate(), []);
        let mut expected = serde_json::to_value(&config).unwrap();
        expected["managed"] = Value::Bool(false);
        assert_eq!(serde_json::to_value(&reparsed).unwrap(), expected);
    }

    #[test]
    fn ownership_is_set_by_the_deployment_mode() {
        let mut value = json!({"schemaVersion": 1});
        assert!(set_managed(&mut value, false));
        assert_eq!(value["managed"], json!(false));
        for mut invalid in [json!([]), json!(null), json!(false), json!(42)] {
            let before = invalid.clone();
            assert!(!set_managed(&mut invalid, false));
            assert_eq!(invalid, before);
        }
    }

    #[test]
    fn expanded_configuration_cannot_export_an_unimportable_oversized_source() {
        let mut config: Config = snix_serde::from_str("{ schemaVersion = 1; }").expect("config");
        config.locale = Some("x".repeat(crate::MAX_SOURCE_BYTES));
        assert!(
            config.validate().is_empty(),
            "the evaluator permits bounded expansion beyond the source limit"
        );
        assert!(export(&config).is_err());
        // Escapes expand, so the limit applies after serialization, not to data length.
        assert!(to_nix(&json!({ "text": "\n".repeat(crate::MAX_SOURCE_BYTES / 2) })).is_err());
    }
}
